toolScript:
let stream = null;
        let mode = 4;
        const video = document.getElementById('video-feed');
        const camBtn = document.getElementById('cam-btn');
        const camPlaceholder = document.getElementById('cam-placeholder');
        const crosshair = document.getElementById('crosshair');
        async function toggleCamera() {
            if (stream) {
                stream.getTracks().forEach(track => track.stop());
                stream = null;
                video.srcObject = null;
                video.classList.add('hidden');
                camPlaceholder.classList.remove('hidden');
                crosshair.classList.add('hidden');
                camBtn.innerText = "Start Camera";
                camBtn.classList.remove('bg-red-500', 'text-white');
                camBtn.classList.add('bg-slate-200');
            } else {
                try {
                    stream = await navigator.mediaDevices.getUserMedia({
                        video: { facingMode: { exact: "environment" }, width: { ideal: 1920 }, height: { ideal: 1080 } }
                    });
                } catch (e) {
                    // Fallback if no environment camera
                    stream = await navigator.mediaDevices.getUserMedia({ video: true });
                }
                video.srcObject = stream;
                video.classList.remove('hidden');
                camPlaceholder.classList.add('hidden');
                crosshair.classList.remove('hidden');
                camBtn.innerText = "Stop Camera";
                camBtn.classList.remove('bg-slate-200');
                camBtn.classList.add('bg-red-500', 'text-white');
            }
        }
        function setZoom(level) {
            video.style.transform = `scale(${level})`;
        }
        function setMode(newMode) {
            mode = parseInt(newMode);
            const band3Group = document.getElementById('group-band3');
            const vBand3 = document.getElementById('v-band3');
            if (mode === 5) {
                band3Group.classList.remove('hidden');
                vBand3.classList.remove('hidden');
            } else {
                band3Group.classList.add('hidden');
                vBand3.classList.add('hidden');
            }
            calculate();
        }
        function calculate() {
            const b1 = parseInt(document.getElementById('sel-band1').value);
            const b2 = parseInt(document.getElementById('sel-band2').value);
            const b3 = parseInt(document.getElementById('sel-band3').value); // only for 5-band
            const mul = parseFloat(document.getElementById('sel-mul').value);
            const tol = document.getElementById('sel-tol');
            const tolVal = tol.options[tol.selectedIndex].text;
            // Visual Updates
            updateBandColor('v-band1', document.getElementById('sel-band1'));
            updateBandColor('v-band2', document.getElementById('sel-band2'));
            if (mode === 5) updateBandColor('v-band3', document.getElementById('sel-band3'));
            updateBandColor('v-band-mul', document.getElementById('sel-mul'));
            updateBandColor('v-band-tol', document.getElementById('sel-tol'));
            let resistance = 0;
            if (mode === 4) {
                resistance = (b1 * 10 + b2) * mul;
            } else {
                resistance = (b1 * 100 + b2 * 10 + b3) * mul;
            }
            // Formatting
            let display = resistance + " Ω";
            if (resistance >= 1000 && resistance < 1000000) {
                display = (resistance / 1000).toFixed(resistance % 1000 === 0 ? 0 : 2) + " kΩ";
            } else if (resistance >= 1000000 && resistance < 1000000000) {
                display = (resistance / 1000000).toFixed(resistance % 1000000 === 0 ? 0 : 2) + " MΩ";
            } else if (resistance >= 1000000000) {
                display = (resistance / 1000000000).toFixed(2) + " GΩ";
            }
            document.getElementById('result-ohm').innerText = display;
            document.getElementById('result-tol').innerText = tolVal.split('(')[1].replace(')', '');
        }
        function updateBandColor(elementId, selectElement) {
            const el = document.getElementById(elementId);
            const selectedOpt = selectElement.options[selectElement.selectedIndex];
            // Remove existing color classes
            el.className = el.className.replace(/c-[a-z]+/g, "").trim();
            // Add new color class based on classList of option
            if (selectedOpt.classList.length > 0) {
                el.classList.add(selectedOpt.classList[0]);
            }
            el.classList.add('band'); // Ensure base class remains
        }
        // Init
        calculate();
